<script setup lang="ts">
import { computed } from 'vue';
import { isTauri } from '@tauri-apps/api/core';
import { ElMessage } from 'element-plus';
import { Activity,Cpu,MemoryStick,HardDrive } from 'lucide-vue-next';
import PageHeader from '../layout/PageHeader.vue';
import {monitorSnapshot,monitorHistory,monitorError,formatBytes,sampleMonitor} from '../monitor';
import {preferences,savePreferences} from '../preferences';
const native=isTauri();
const memory=computed(()=>{const s=monitorSnapshot.value;return s?.memory_total&&s.memory_used!=null?s.memory_used/s.memory_total*100:null;});
const free=computed(()=>{const s=monitorSnapshot.value;return s?.disk_total&&s.disk_available!=null?s.disk_available/s.disk_total*100:null;});
function points(kind:'cpu'|'memory'){return monitorHistory.value.map((s,i)=>{const value=kind==='cpu'?s.cpu_percent:s.memory_total&&s.memory_used!=null?s.memory_used/s.memory_total*100:null;return value==null?null:`${i*600/Math.max(1,monitorHistory.value.length-1)},${90-value*.8}`}).filter(Boolean).join(' ');}
async function toggle(value:boolean){try{await savePreferences({monitor_enabled:value});}catch(error){ElMessage.error(String(error));}}
</script>
<template><main class="monitor-page"><PageHeader title="本机监控" subtitle="轻量观察资源使用与后台任务，不扫描应用文件。"><template #actions><el-switch :model-value="preferences.monitor_enabled" :disabled="!native" active-text="资源采样" aria-label="启用资源采样" @change="toggle(Boolean($event))"/><el-button :disabled="!native||!preferences.monitor_enabled" @click="sampleMonitor">刷新采样</el-button></template></PageHeader><div class="monitor-content"><div v-if="!native" class="notice"><Activity :size="40"/><h2>本机资源，在这里看清</h2><p>请在桌面应用中查看 CPU、内存和磁盘统计。</p></div><template v-else><el-alert v-if="monitorError" title="采样未完成" :description="monitorError" type="warning" :closable="false"/><el-alert v-if="!preferences.monitor_enabled" title="资源采样已关闭，以下保留最后一次采样" type="info" :closable="false"/><div class="metrics"><article><Cpu/><span>CPU 使用率</span><strong>{{ monitorSnapshot?.cpu_percent==null?'—':monitorSnapshot.cpu_percent.toFixed(1)+'%' }}</strong><p>两次采样之间的平均使用率</p></article><article><MemoryStick/><span>内存使用</span><strong>{{ memory==null?'—':memory.toFixed(1)+'%' }}</strong><p>{{ formatBytes(monitorSnapshot?.memory_used) }} / {{ formatBytes(monitorSnapshot?.memory_total) }}</p></article><article><HardDrive/><span>磁盘可用</span><strong>{{ formatBytes(monitorSnapshot?.disk_available) }}</strong><p>{{ free==null?'—':free.toFixed(1)+'% 可用' }} · 用户目录所在磁盘</p></article></div><section class="chart"><div><h2>近期采样</h2><span><i class="cpu"/>CPU <i class="memory"/>内存</span></div><svg viewBox="0 0 600 110" role="img" aria-label="最近最多60次 CPU 与内存使用率采样"><path d="M0 10H600M0 50H600M0 90H600" stroke="#a78bfa13"/><polyline :points="points('cpu')" fill="none" stroke="#a78bfa" stroke-width="2"/><polyline :points="points('memory')" fill="none" stroke="#64d5e9" stroke-width="2"/></svg><p>{{ monitorHistory.length }} 次采样 · 每 2.5 秒读取一次 · 最多保留 60 次，仅限本次应用会话；暂停后保留最后采样</p></section><div class="notes"><p v-if="monitorSnapshot">最近采样：{{ new Date(monitorSnapshot.sampled_at).toLocaleTimeString() }} · 磁盘每 30 秒刷新</p><p v-for="note in monitorSnapshot?.warnings" :key="note">{{ note }}</p><p>数据仅在本机读取与显示。首次 CPU 采样、权限不足或不支持的指标显示为 —。</p></div></template></div></main></template>
<style scoped>
.monitor-page{height:100%;display:flex;flex-direction:column}.monitor-content{padding:20px 28px;overflow:auto;flex:1;min-height:0}.metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:0 0 24px}.metrics article{position:relative;padding:22px;border:1px solid #a78bfa20;border-radius:16px;background:radial-gradient(ellipse at 100% 0,#a78bfa17,transparent),#ffffff03}.metrics svg{width:19px;color:#a78bfa;position:absolute;right:20px;top:20px}.metrics span{font-size:11px;color:#a395b8;display:block}.metrics strong{display:block;font-size:28px;color:#ede5ff;margin:18px 0 8px;font-weight:500}.metrics p{font-size:10px;color:#897a9e;margin:0;line-height:1.7}.chart{border:1px solid #a78bfa18;background:#ffffff03;padding:20px;border-radius:16px}.chart>div{display:flex;align-items:center;justify-content:space-between}.chart h2{font-size:14px;font-weight:500;margin:0}.chart span{font-size:10px;color:#9e8bb5;display:flex;align-items:center;gap:7px}.chart i{width:5px;height:5px;border-radius:50%;display:inline-block}.cpu{background:#a78bfa}.memory{background:#64d5e9}.chart svg{width:100%;height:170px;margin-top:20px}.chart p,.notes p{font-size:10px;color:#8a7b9e;line-height:1.8}.notes{padding-top:15px}.notice{display:flex;min-height:350px;align-items:center;justify-content:center;flex-direction:column;color:#ac93dc}.notice h2{font-size:20px;color:#e0d5f6}.notice p{font-size:12px;color:#9786ad}:deep(.el-alert){margin-bottom:18px}@media(max-width:900px){.monitor-content{padding:18px 20px}.metrics article{padding:18px 15px}.metrics strong{font-size:23px}}@media(max-width:700px){.metrics{grid-template-columns:1fr}.chart svg{height:120px}}
</style>
